import { bigint, timestamp, uuid } from 'drizzle-orm/pg-core';

/** UUID primary key, generated by Postgres. */
export const id = () => uuid().primaryKey().defaultRandom();

/** timestamptz, always UTC, mapped to JS Date. */
export const tstz = () => timestamp({ withTimezone: true, mode: 'date' });

/** Money: integer cents in EUR, mapped to JS bigint (never a float). */
export const cents = () => bigint({ mode: 'bigint' });

export const timestamps = {
  createdAt: tstz().notNull().defaultNow(),
  updatedAt: tstz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};
